OUT=os.path.join(os.path.dirname(__file__),'Intelligent_Mine_Three_Presentation_Flows.pdf')
NAVY=HexColor('#102A43'); TEAL=HexColor('#087E8B'); GOLD=HexColor('#E6A23C'); INK=HexColor('#243B53'); MUTED=HexColor('#627D98'); PALE=HexColor('#F0F6F8'); SAND=HexColor('#FBF5E9'); WHITE=colors.white
ss=getSampleStyleSheet()
ss.add(ParagraphStyle(name='CoverTitle',parent=ss['Title'],fontName='Helvetica-Bold',fontSize=30,leading=35,textColor=WHITE,alignment=TA_LEFT,spaceAfter=18))
ss.add(ParagraphStyle(name='CoverSub',parent=ss['Normal'],fontName='Helvetica',fontSize=13,leading=19,textColor=HexColor('#D9EAF0')))
ss.add(ParagraphStyle(name='H1x',parent=ss['Heading1'],fontName='Helvetica-Bold',fontSize=22,leading=27,textColor=NAVY,spaceAfter=10))
ss.add(ParagraphStyle(name='H2x',parent=ss['Heading2'],fontName='Helvetica-Bold',fontSize=14,leading=18,textColor=TEAL,spaceBefore=8,spaceAfter=6))
ss.add(ParagraphStyle(name='Bodyx',parent=ss['BodyText'],fontName='Helvetica',fontSize=9.1,leading=12.6,textColor=INK,spaceAfter=5))
ss.add(ParagraphStyle(name='Smallx',parent=ss['BodyText'],fontName='Helvetica',fontSize=7.8,leading=10,textColor=MUTED,spaceAfter=2))
ss.add(ParagraphStyle(name='CardTitle',parent=ss['Heading2'],fontName='Helvetica-Bold',fontSize=12.2,leading=15,textColor=NAVY,spaceAfter=4))
ss.add(ParagraphStyle(name='Label',parent=ss['Normal'],fontName='Helvetica-Bold',fontSize=7.2,leading=9,textColor=TEAL,spaceAfter=2))
def P(s,style='Bodyx'): return Paragraph(s,ss[style])
def footer(c,d):
    if d.page==1:return
    w,h=letter;c.saveState();c.setStrokeColor(HexColor('#D9E2EC'));c.line(.68*inch,.52*inch,w-.68*inch,.52*inch);c.setFont('Helvetica',7.5);c.setFillColor(MUTED);c.drawString(.68*inch,.34*inch,'THE INTELLIGENT MINE  /  TECHNICAL TRACK');c.drawRightString(w-.68*inch,.34*inch,str(d.page));c.restoreState()
def band(title,sub,tag):
    t=Table([[P(tag.upper(),'Label')],[P(title,'H1x')],[P(sub)]],colWidths=[7.15*inch]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),PALE),('LEFTPADDING',(0,0),(-1,-1),15),('RIGHTPADDING',(0,0),(-1,-1),15),('TOPPADDING',(0,0),(-1,0),11),('BOTTOMPADDING',(0,-1),(-1,-1),9)]));return t
def card(label,title,content,fill=WHITE):
    els=[P(label.upper(),'Label'),P(title,'CardTitle')]
    els += [P(content)] if isinstance(content,str) else content
    t=Table([[els]],colWidths=[7.12*inch]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),fill),('BOX',(0,0),(-1,-1),.6,HexColor('#D9E2EC')),('LINEBEFORE',(0,0),(0,-1),3,TEAL),('LEFTPADDING',(0,0),(-1,-1),12),('RIGHTPADDING',(0,0),(-1,-1),12),('TOPPADDING',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),8)]));return t

# Slide: title, minutes, scene, spoken narrative, visual, audience cue, transition, demo cue.
F=[
('The Signal in the Noise','A high-stakes discovery story: find the right ground, earn the right to drill, then keep every decision connected.','A board has one field season, a fixed exploration budget and three competing target areas. The team must decide where to look before the window closes.',[
('The decision before the first drill hole',2,'At 07:10, the exploration director receives three candidate concessions and one uncomfortable question: which target deserves the next dollar?','Open with the human constraint: limited capital, a short field window and incomplete evidence. The old workflow means separate spreadsheets, map screenshots, consultant emails and a late committee pack. Frame the talk as a connected decision trail from opportunity to closure.','Full-bleed Ghana landscape, three target pins and one budget clock.','Ask the room to picture defending a target when the data lives in five inboxes.','We begin before the rig moves: first establish what is happening across the landscape.','Hold on the three pins; no demo yet.'),
('MineSentinel: establish the landscape',4,'The analyst opens MineSentinel to see mines, production context, concession visibility and a geographic view in one place.','Show how shared mining context gives the team an initial map of assets and activity. Use it to identify where to investigate. Boundary: this is screening context, not a commodity-price forecaster or hyperspectral target detector unless integrations are verified.','Map zooms from national context to concession and nearby operations.','Point to the analyst, who needs a sourceable starting point rather than another manual compilation.','A map shows where the question sits. MineAsk turns that question into structured assessment.','Walk through lookup and map-to-report only if available in the demo.'),
('MineAsk: turn a location into a decision brief',5,'The team asks: what is known about title, access, environmental context and nearby infrastructure around Target B?','Describe MineAsk as a query-and-assess workspace joining available mining and geospatial evidence. It can structure first-pass analysis and surface issues for verification. Show source lineage and confidence. A red flag is a prompt to investigate, not an automated legal conclusion.','Evidence dossier: question, map, source snippets and open checks.','Notice the distinction between evidence, inference and unresolved verification.','The desk assessment narrows the field. Geological evidence must now rank where boots and drills go.','Open a cited evidence item; avoid autonomous legal-advice claims.'),
('TerraPulse: rank targets with geological evidence',5,'Geologists combine satellite, geophysical, geochemical and structural information to prioritize target areas before mobilization.','TerraPulse brings layers into a shared geospatial workflow to identify, rank and explain prospective targets. ML may support prioritization where validated; geologists remain accountable. A high-ranked target is not a declared resource.','Evidence layers resolve into three target polygons and a validation checklist.','Better allocation of scarce field effort, not guaranteed discovery.','The team chooses a target, but discovery is not yet a bankable model.','Show a ranked target only if present in the product; label sample values illustrative.'),
('From target to evidence: the learning loop',4,'Field teams collect observations and assays. New evidence challenges the model: one target weakens; another gains support.','Tell the iteration story. New drill and field evidence should flow back into interpretation with provenance, competent review and formal standards. TerraPulse supports, rather than replaces, field validation, 3D modeling or formal resource/reserve reporting.','Before/after ranking with an explicit new-data marker.','Intelligence learns with accountable review; it does not remove geological judgment.','A defensible opportunity needs permitting, social context and operating plans to keep pace.','Use hypothetical refreshed data unless confirmed in the live product.'),
('MineAsk keeps the wider context visible',3,'Before committing, the team checks licensing pathway, land and community context, water, access and constraints requiring official confirmation.','MineAsk can help assemble a location-focused evidence pack from available sources. Broader live regulatory NLP, sentiment scanning, GPS enforcement and blockchain traceability are part of the session vision, not established MineAsk functions in the notes.','Opportunity map with constraint overlays and verify-with-authority panel.','Screening evidence is not regulatory approval or social consent.','With the opportunity understood, the operating mine needs a shared picture that changes as the site changes.','Do not simulate alerts unless there is a verified working feature.'),
('MyMine: make the plan visible together',4,'Planners, geotech, HSE and maintenance review a shared AR mine model on headset, tablet, phone or web.','MyMine’s stated features include a shared 3D/AR twin, streaming and multi-user collaboration; an edge node is described for weak connectivity. Use it for common spatial context. Do not claim it replaces mine planning, dispatch or certified safety systems.','One pit view and several collaborators sharing context.','See how a common spatial reference can improve the quality of a conversation.','The journey continues after review: measure what changed and plan closure early.','Demonstrate only the AR twin, streaming and device modes confirmed in the build.'),
('Closure starts with decisions made today',3,'At year-end, the team assembles an evidence trail of choices, checks and field validations.','Close the lifecycle arc: disciplined information practices can support operational reporting and future rehabilitation planning. ESG sensors, automated audit-ready reports and AI closure modeling are session aspirations; do not attribute them to the four products without verified integrations.','Timeline from target selection to review, ending in closure planning.','Promise connected decision quality and less duplication; propose measured pilots, not invented ROI.','The signal was never one magic model. It was a traceable chain of decisions.','“Connect the evidence before you connect the machines.”')]),
('The Permit Clock','A regulatory-pressure story: a promising asset is at risk of losing time because no one sees the whole picture soon enough.','A project team prepares for an investment gate. The technical case looks promising, but licensing, land and access information is fragmented.',[
('The meeting that starts with a red folder',2,'A sponsor has 30 minutes before the investment committee. The map, production references, title notes and environmental questions live in different files.','The team is not short of data; it is short of a shared, reviewable answer. Promise a walkthrough of how intelligence helps teams ask better questions earlier.','Committee table with map fragments spilling from a red folder.','Ask what the audience wants to know before detailed diligence.','First establish opportunity context, then test the location and carry a common picture forward.','Use a fictional project; no real permit allegation.'),
('MineSentinel: find the project in its sector',3,'The analyst locates the project among mines, concessions and production context.','MineSentinel is described as mining map, production analytics, concession visibility, GIS dashboards and report exports. This establishes the where and sector context. The files do not establish complete regulator-grade coverage or real-time updates.','National map zooms to district and related mining context.','Show how geography surfaces useful questions before deep diligence.','Sector context is useful; the committee’s question is asset-specific.','Use only verified product data and freshness statements.'),
('MineAsk: ask what can change the decision',5,'The analyst structures an assessment of title, overlap, licensing steps, roads, water, protected areas, settlement and access.','MineAsk supports query-and-assess analysis across available mining, geospatial, environmental, regulatory and market context. It helps with screening and issue triage. Some monitoring, alerts and reporting are partial or roadmap; be candid.','Question cards link to map, evidence and needs-verification column.','Show not only a score, but what supports it and what is unknown.','The due-diligence question is now a target question: where should technical teams spend field time?','Keep sourced, inferred and official-check labels distinct.'),
('TerraPulse: focus fieldwork on the strongest case',5,'The technical team compares available evidence and prioritizes targets before mobilization.','TerraPulse brings satellite, geophysical, geochemical and structural inputs into a shared workflow to identify and rank targets. Ranking is decision support; ground truth and geological review remain essential.','Target ranking beside a field-validation checklist.','Tie value to avoided low-value work and released expert capacity; measure it in a pilot.','The committee now has a better-informed location decision. Operations need a shared model to coordinate execution.','Label target values hypothetical unless generated by a confirmed build.'),
('The evidence pack travels with the decision',3,'The investment memo contains source-aware maps, evidence, confidence and open items needing legal or field confirmation.','A decision is stronger when reviewers trace claims to evidence. MineAsk notes source lineage/confidence and collaboration/exports, with maturity varying by capability. Generated text is not a legal opinion or permit approval.','Memo with evidence, inference and open-action side rail.','An AI layer can increase review discipline rather than hide uncertainty.','After approval, teams still align plans with conditions on the ground.','Use actual export and provenance features only if present.'),
('MyMine: bring the same context into the mine review',5,'Operations and technical teams gather around an AR twin; remote specialists share the same 3D view.','MyMine’s stated proposition is shared AR, streaming and multi-user viewing across devices, with edge sync for weak networks. It makes spatial discussion tangible. Live plan integrations, geofence alerts, maintenance overlays and safety outcomes are unverified.','Shared twin with reviewers and an annotated work area.','Move from boardroom evidence to a shared site conversation.','The project does not end when it produces ore. Closure obligations should be visible while choices are still being made.','Distinguish illustrative annotations from actual overlays.'),
('From compliance burden to evidence habit',4,'The team adopts a recurring review: confirm changes, record evidence, assign verification and preserve decision context.','Widen to the intelligent-mine vision: NLP may monitor regulation, telematics evidence activity, remote sensing observes land disturbance and traceability links material. These need integrations and validation; they are not claims about these products.','Connected value-chain diagram, solid lines for scope and dotted lines for future links.','Alignment means owners, sources, timestamps and review, not software declaring compliance.','A project that sees risk earlier can also plan responsibly for its final chapter.','Do not claim software ensures compliance or prevents violations.'),
('Final gate: close responsibly and prove progress',3,'The sponsor leaves with a staged plan: validate data, pilot a workflow, measure turnaround and define integrations.','Offer a practical framework: evaluate connectivity across the chain, data trust, adoption and measured outcomes. Rehabilitation and ESG reporting are architecture outcomes, not current product claims.','Four gates: data trust, workflow fit, integration, measured value.','Earlier evidence matters when it changes a decision and stays reviewable.','The red folder becomes a living decision trail.','Finish with recap; no Q&A is scheduled.')]),
('One Mine, Four Viewpoints','A people-first story: follow one fictional mine as a geologist, analyst, operator and community-facing leader see the same asset differently.','At dawn, Ama the geologist, Kojo the analyst, Esi the compliance lead and Yaw the planner each receive a different version of the same mine.',[
('Four people, four versions of one mine',2,'Ama has targets; Kojo has a spreadsheet; Esi has a permit checklist; Yaw has a plan view. Their decisions collide at the weekly review.','Introduce the thesis through people, not product menus. Each function sees a slice and handoffs lose assumptions. The goal is one connected intelligence layer with human review.','Four screens converge toward one Ghana mine outline.','Name the characters and the decision each owns.','First they need shared context: what is happening around the asset?','Use fictional characters, mine and data.'),
('Kojo opens MineSentinel: where does the asset sit?',4,'The analyst starts with mining map, concession visibility, production context and GIS dashboard.','Show how sector context helps locate assets and ask the next question. Exportable reports can support a briefing where available. Be transparent about source coverage and update cadence.','Map toggles to production context and an export preview.','The overview supports faster, consistent preparation, not guaranteed investment alpha.','Kojo sees the landscape. Esi needs site-specific risks and open checks.','Show the real product journey only if supported.'),
('Esi asks MineAsk: what must we verify?',5,'Esi asks about licensing pathway, overlap, water, protected-area context, road access and nearby settlements.','MineAsk structures a first pass from available sources. Esi separates evidence, interpretation and official checks. Continuous monitoring and sentiment alerts are not established as live features in the note.','Three columns: sourced, inferred, verify.','AI makes uncertainty legible; people remain responsible for review and engagement.','With constraints visible, Ama can focus exploration work.','Show query-answer-dossier, not autonomous approval.'),
('Ama uses TerraPulse: layers to field plan',5,'Ama compares satellite, geophysical, geochemical and structural evidence and prioritizes two targets for field validation.','TerraPulse organizes inputs, ranks and explains targets. Ama writes the field plan and records observations that challenge the ranking. Formal resource estimates need the appropriate validated workflow and competent persons.','Evidence layers become targets with validation actions.','Better allocation and faster synthesis, subject to pilot measurement.','A target becomes a working mine only when the plan is understood across disciplines.','Label rankings hypothetical unless shown by the product.'),
('Yaw brings the room into MyMine',5,'Yaw opens a shared AR mine twin. On-site and remote colleagues share a 3D context by headset, tablet, phone or web.','The MyMine proposition includes shared 3D/AR, streaming, multi-user collaboration and edge support. It creates a common spatial reference. Predictive maintenance, autonomous optimization or safety gains are not established.','Annotated model with collaborators on different devices.','Imagine replacing “which plan are you looking at?” with a shared view.','A connected review is powerful when inputs and caveats remain visible.','Preselect a simple verified scene to protect timing.'),
('One question, four disciplines',3,'A proposed access change affects target access, environmental buffers, haul-road planning and future rehabilitation.','Play a short dialogue: geologist identifies target value; compliance lead raises a constraint; planner shows route; analyst asks what evidence changes the investment case. Products connect parts of this discussion; integrations must be validated.','Four viewpoints converge on one map/twin.','The value is workflow connectivity, not just software connectivity.','Widen the lens: which intelligent capabilities exist today, and which are next?','Label the scenario illustrative.'),
('Intelligent layer: today and next',3,'Distinguish product scope from the wider vision: forecasting, NLP regulation, telematics, remote sensing, traceability, plant optimization, logistics and closure modeling.','Position the sequence clearly: MineSentinel for landscape context; MineAsk for evidence-backed assessment; TerraPulse for exploration targets; MyMine for shared spatial review. Wider capabilities require connectors, governance and validation.','Solid blocks for supported workflows; dotted modules for future integrations.','Ask whether a tool connects decisions, evidence and accountable people across handoffs.','A final framework turns the story into an investment test.','Do not imply every box is an existing capability.'),
('Leave the audience with a practical test',3,'The team pilots one workflow with baselines, trusted sources, named reviewers and a decision that could change.','Offer five tests: decision importance, provenance/freshness, cross-functional handoff, integration/adoption and measurable outcome. Design ESG and closure early, with owners and verification. Avoid promised savings.','Pilot card: workflow, owner, baseline, integration and review gate.','Challenge: connect the next decision, then prove the value.','One mine. Four viewpoints. A shared and reviewable story.','Close without Q&A, as specified.')])]

doc=SimpleDocTemplate(OUT,pagesize=letter,rightMargin=.68*inch,leftMargin=.68*inch,topMargin=.62*inch,bottomMargin=.72*inch,title='The Intelligent Mine: Three Presentation Flows',author='Technical Track Presentation Planning')
story=[]
cover=Table([[[P('TECHNICAL TRACK  /  SOLO PRESENTATION  /  30 MINUTES','Label'),Spacer(1,1.0*inch),P('THE<br/>INTELLIGENT<br/>MINE','CoverTitle'),P('Three detailed story-led presentation flows','CoverSub'),Spacer(1,.35*inch),P('Connecting AI across the full value chain - from first drill hole to final rehabilitation','CoverSub'),Spacer(1,1.25*inch),P('A speaker-ready walkthrough blueprint for MineSentinel, MineAsk, TerraPulse and MyMine AR Mine Digital Twin','CoverSub')]]],colWidths=[7.15*inch],rowHeights=[9.1*inch]);cover.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),NAVY),('LEFTPADDING',(0,0),(-1,-1),32),('RIGHTPADDING',(0,0),(-1,-1),28),('TOPPADDING',(0,0),(-1,-1),30),('VALIGN',(0,0),(-1,-1),'TOP')]))
story += [cover,PageBreak(),band('How to use this blueprint','Choose one flow for the 30-minute solo address. Each is a complete beginning-to-end narrative, ordered around the four products and anchored in one fictional Ghana mining project.','Speaker guide'),Spacer(1,12),P('The session is a standalone address with visual aid and no Q&A. Each flow uses eight slides and totals 30 minutes. Slide pages provide the story beat, suggested spoken content, stage direction, audience cue, transition and demo cue. These are three narrative options, not separate product pitches.'),P('The shared product sequence','H2x')]
seq=Table([[P('<b>1 / MineSentinel</b><br/>Landscape intelligence'),P('<b>2 / MineAsk</b><br/>Evidence-backed assessment'),P('<b>3 / TerraPulse</b><br/>Exploration targeting'),P('<b>4 / MyMine</b><br/>Shared AR mine twin')]],colWidths=[1.79*inch]*4);seq.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),PALE),('BOX',(0,0),(-1,-1),.5,HexColor('#D9E2EC')),('INNERGRID',(0,0),(-1,-1),.5,WHITE),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),9)]));story += [seq,P('Claim discipline for the stage','H2x'),P('<b>Product scope:</b> MineSentinel is described as a map, production analytics, concession visibility and GIS intelligence concept. MineAsk centers on query-and-assess workflows using available mining/geospatial evidence; some monitoring and reporting is partial or planned. TerraPulse is a proposed exploration workflow integrating geospatial and survey evidence to rank targets; it supports, rather than replaces, geological judgment and formal estimation. MyMine’s source describes a shared AR twin, streaming and multi-user access, with edge sync stated by the owner; many operational overlays remain unverified.'),P('<b>Session vision:</b> forecasting, autonomous equipment, plant optimization, regulatory NLP, sentiment analysis, blockchain traceability and AI closure modeling are connected-stack examples from the session brief. Present them as ecosystem vision or integration opportunities unless independently verified in the product build. Do not promise quantified savings, compliance, discoveries, recovery gains or safety outcomes.'),PageBreak()]
