for title,body in [('One storyline','Use one fictional mine and return to the same people, decision and location throughout.'),('One visual grammar','Keep maps, evidence cards, target rankings and the twin consistent. Use solid styling for described capabilities and dotted styling for future integrations.'),('One explicit caveat','Where data coverage, update cadence, model accuracy or product maturity is unverified, say so briefly.'),('One outcome frame','Describe benefits as mechanisms to validate: less duplicated research, focused field activity, stronger shared understanding and reviewability.'),('One 30-minute clock','Rehearse to the schedule. Trim optional detail, not the opening conflict or final takeaway.')]:story += [card('Rehearsal check',title,body,PALE),Spacer(1,7)]
